import 'models.dart';

/// How much of a kind of video 为你推荐 shows.
enum FeedLevel {
  /// Not touched.
  off,
  /// Ranked far down, so only strong matches show.
  reduce,
  /// Left out.
  drop;

  static FeedLevel parse(Object? raw, FeedLevel fallback) {
    for (final level in values) {
      if (level.name == raw) return level;
    }
    return fallback;
  }
}

/// The kinds of video 为你推荐 can show less of, and how much less.
class FeedMix {
  const FeedMix({this.musicTracks = FeedLevel.off, this.shorts = FeedLevel.off, this.vertical = FeedLevel.off});
  /// YouTube Music's auto-generated tracks (not music videos).
  final FeedLevel musicTracks;
  final FeedLevel shorts;
  final FeedLevel vertical;

  /// Score taken off a video of a reduced kind; a good match scores about
  /// 2 to 4, so this pushes it below nearly everything else.
  static const reducePenalty = 2.5;

  /// The score to take off [item], or null when it is left out.
  double? penaltyOf(VideoItem item) {
    var penalty = 0.0;
    for (final (level, matches) in [
      (musicTracks, isMusicTrack),
      (shorts, isShort),
      (vertical, isVertical),
    ]) {
      if (level == FeedLevel.off || !matches(item)) continue;
      if (level == FeedLevel.drop) return null;
      penalty += reducePenalty;
    }
    return penalty;
  }
}

final _topicChannel = RegExp(r'\s[-–—]\s*(Topic|主题|主題|トピック|주제)\s*$', caseSensitive: false);
final _autoGenerated = RegExp(r'^\s*(Provided to YouTube by|Auto-generated by YouTube)', caseSensitive: false);
final _musicVideo = RegExp(r'official\s+(music\s+)?video|music\s+video|\bMV\b|官方\s*MV|官方.{0,3}音乐视频|ミュージックビデオ', caseSensitive: false);

/// A YouTube Music "Art Track": auto-generated audio with album art, from a
/// "… - Topic" channel. A video titled as a music video is not one.
bool isMusicTrack(VideoItem item) {
  if (_musicVideo.hasMatch(item.title)) return false;
  return _topicChannel.hasMatch(item.channel) ||
      _autoGenerated.hasMatch(item.description ?? '') ||
      item.url.contains('music.youtube.com');
}

/// A Short: a /shorts/ address, a minute or less, or up to three minutes
/// tagged #shorts.
bool isShort(VideoItem item) {
  if (item.isShortListing || item.url.contains('/shorts/')) return true;
  final seconds = item.duration;
  if (seconds == null || seconds <= 0) return false;
  return seconds <= 60 || (seconds <= 180 && RegExp(r'#shorts?\b', caseSensitive: false).hasMatch('${item.title} ${item.description ?? ''}'));
}

/// Taller than wide, when the frame size is known.
bool isVertical(VideoItem item) {
  final width = item.width;
  final height = item.height;
  return width != null && height != null && width > 0 && height > width;
}
